<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Nota {{ $order->order_code }}</title><style>body{font:14px Arial,sans-serif;max-width:720px;margin:35px auto;color:#222}.center{text-align:center}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{padding:9px 5px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}.total{font-size:18px;font-weight:bold;margin-top:20px;text-align:right}.muted{color:#666}@media print{button{display:none}}</style></head><body><button onclick="print()">Cetak</button><div class="center"><h2>Laundry</h2><div>Nota transaksi</div></div><hr><p><b>Kode order:</b> {{ $order->order_code }}<br><b>Pelanggan:</b> {{ $order->customer_name }} · {{ $order->customer_phone }}<br><b>Tanggal masuk:</b> {{ $order->entry_date->format('d/m/Y') }}<br><b>Estimasi selesai:</b> {{ $order->estimated_finish_date->format('d/m/Y') }}</p><table><thead><tr><th>Layanan</th><th class="right">Harga</th><th class="right">Qty</th><th class="right">Subtotal</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->item_name }}</td><td class="right">Rp {{ number_format($item->item_price,0,',','.') }}</td><td class="right">{{ $item->qty }} {{ $item->unit }}</td><td class="right">Rp {{ number_format($item->subtotal,0,',','.') }}</td></tr>@endforeach</tbody></table><div class="total">TOTAL: Rp {{ number_format($order->total_price,0,',','.') }}</div>@if($order->notes)<p><b>Catatan:</b> {{ $order->notes }}</p>@endif<p class="center muted" style="margin-top:48px">Terima kasih telah menggunakan layanan kami.</p></body></html>
